import { useEffect,useMemo,useState } from 'react'
import { Activity,AlertTriangle,ArrowLeft,CalendarClock,ChevronRight,BedDouble,Plus,Download,FileClock,FolderOpen,ListTree,Microscope,Pill,PlayCircle,Printer,RefreshCcw,ShieldCheck,Trash2,UserRound,ArrowRightLeft,LogOut,Stethoscope } from 'lucide-react'
import { useLocation,useParams } from 'react-router-dom'
import { Page } from '../../design-system/Page'
import { EntityRecordShell } from '../../design-system/EntityRecordShell'
import { PrintExportActions } from '../../design-system/PrintExportActions'
import { Button } from '../../design-system/Button'
import { OverflowMenu } from '../../design-system/OverflowMenu'
import { SaveButton } from '../../design-system/SaveButton'
import { ManualDateField } from '../../design-system/ManualDateField'
import { TimeField } from '../../design-system/TimeField'
import { ObserverDialog } from '../../design-system/ObserverDialog'
import { EmptyState } from '../../design-system/EmptyState'
import { DocumentsWorkspace } from '../../design-system/DocumentsWorkspace'
import { useLanguage,translate} from '../../core/i18n/LanguageContext'
import { useFeedback } from '../../core/feedback/FeedbackContext'
import { useTenant } from '../../core/tenant/TenantContext'
import { useAuditActor } from '../../core/audit/useAuditActor'
import { useContextualNavigation } from '../../core/navigation/useContextualNavigation'
import { useRecordSequenceNavigation } from '../../core/navigation/useRecordSequenceNavigation'
import { downloadRecordJson } from '../../core/export/recordExport'
import { can,CAPABILITIES } from '../../core/permissions/roles'
import { createAdmission,dischargeAdmission,loadAdmissions,loadPatients,transferAdmission } from '../patients/patientsService'
import { PatientSummaryActions } from '../patients/PatientSummaryActions'
import { loadDepartments } from '../management/departmentsService'
import { loadManagementLibraries,createManagementLibraryItem } from '../management/managementCloudService'
import { demoLibrarySeed } from '../management/managementData'
import { useLaboratoryRegistry } from '../laboratory/hooks/useLaboratoryRegistry'
import { linkLaboratorySampleToSurveillance } from '../laboratory/laboratoryLinkService'
import { NewSurveillanceFlow } from './NewSurveillanceFlow'
import { SurveillanceJourneyGuidance,SurveillanceJourneyMap } from './SurveillanceJourneyMap'
import './surveillanceEpisode.css'
import { createClinicalRepository } from './clinicalRepository'
import { evaluateHaiCriteria, haiCriteriaSetForType } from './haiCriteriaDefinitions'
import { loadHaiCriteriaSets } from './haiCriteriaLibraryService'
