export function PatientClinicalCanonicalPage({patientMode=false}){
  const actor=useAuditActor()
  const {caseId,patientId}=useParams()
  const location=useLocation()
  const {t,language,locale}=useLanguage()
  const {notify}=useFeedback()
  const {tenant,isDemo,role,membership,canAccessRecord}=useTenant()
  const {goBack,restored}=useContextualNavigation(patientMode?'/patients':'/surveillance')
  const repository=useMemo(()=>createClinicalRepository({isDemo,organizationId:tenant?.id,actor}),[isDemo,tenant?.id,actor])
  const laboratory=useLaboratoryRegistry()
  const [patients,setPatients]=useState([]),[episodes,setEpisodes]=useState([]),[admissions,setAdmissions]=useState([]),[departments,setDepartments]=useState([]),[clinicalLibraries,setClinicalLibraries]=useState(demoLibrarySeed)
  // Demo has no cloud attachment store; keep documents per episode in memory.
  const [demoDocuments,setDemoDocuments]=useState({})
  const [riskFlagRows,setRiskFlagRows]=useState({})
  const [selectedAdmissionId,setSelectedAdmissionId]=useState(()=>patientMode?(location.state?.admissionId||''):'')
  const [selectedEpisodeId,setSelectedEpisodeId]=useState(caseId||''),[loading,setLoading]=useState(true),[error,setError]=useState(''),[createOpen,setCreateOpen]=useState(false)
  const [sampleToLink,setSampleToLink]=useState(null)
  const [clearTestOpen,setClearTestOpen]=useState(false)
  const creatingAdmissionSampleRef=useMemo(()=>({current:false}),[])
  const [tab,setTab]=useState(()=>location.state?.openTab||restored?.tab||'summary')
  const has=cap=>can(role,cap,membership?.capabilities??[],membership?.customCapabilities??[])
  const patient=useMemo(()=>patientMode?patients.find(row=>String(row.id)===String(patientId))||null:patients.find(row=>episodes.some(ep=>episodeBelongsToPatient(ep,row)))||null,[patients,patientMode,patientId,episodes])
  const selectedAdmission=patientMode?admissions.find(row=>String(row.id)===String(selectedAdmissionId))||null:null
  const admissionEpisodes=useMemo(()=>{
    const visible=episodes.filter(ep=>ep.status!=='cancelled')
    if(!patientMode||!selectedAdmission)return visible
    return visible.filter(ep=>{
      if(ep.admissionId)return String(ep.admissionId)===String(selectedAdmission.id)
      const started=String(ep.startedAt||'').slice(0,10)
      const inDates=started&&started>=String(selectedAdmission.admissionDate||'')&&(!selectedAdmission.dischargeDate||started<=String(selectedAdmission.dischargeDate))
      const sameDepartment=!selectedAdmission.departmentId||!ep.departmentId||String(selectedAdmission.departmentId)===String(ep.departmentId)
      return Boolean(inDates&&sameDepartment)
    })
  },[episodes,patientMode,selectedAdmission])
  const admissionSamples=useMemo(()=>{
    if(!patientMode||!selectedAdmission||!patient)return []
    return (laboratory.rows||[]).filter(sample=>{
      const samePatient=(patient.recordId&&sample.patientRecordId)?String(sample.patientRecordId)===String(patient.recordId):String(sample.patientId||'')===String(patient.id||'')
      if(!samePatient)return false
      const date=String(sample.collectedAt||sample.requestedAt||'').slice(0,10)
      const inDates=!date||(date>=String(selectedAdmission.admissionDate||'')&&(!selectedAdmission.dischargeDate||date<=String(selectedAdmission.dischargeDate)))
      const sameDepartment=!selectedAdmission.departmentId||!sample.departmentId||String(sample.departmentId)===String(selectedAdmission.departmentId)
      return inDates&&sameDepartment
    })
  },[laboratory.rows,patientMode,selectedAdmission,patient])
  const record=(patientMode?(selectedAdmission?(admissionEpisodes.find(row=>String(row.id)===String(selectedEpisodeId))||admissionEpisodes[0]||null):null):(episodes.find(row=>String(row.id)===String(selectedEpisodeId))||episodes[0]||null))
  // Episode route (/surveillance/:id): the episode's own samples plus any laboratory
  // rows recorded for it afterwards (e.g. a follow-up sample), so new entries show up.
  const recordSamples=useMemo(()=>{
    if(patientMode||!record)return []
    const base=record.samples||[]
    const ids=new Set(base.map(x=>String(x.id||'')))
    const extra=(laboratory.rows||[]).filter(sample=>{
      const code=String(sample.id||'')
      if(ids.has(code))return false
      const linked=String(sample.surveillanceCase||sample.surveillanceCaseId||'')===String(record.id)
      const followUp=[...ids].some(id=>id&&code.startsWith(`${id}-R`))
      return linked||followUp
    }).map(sample=>({...sample,surveillanceCase:sample.surveillanceCase||record.id}))
    return [...base,...extra]
  },[patientMode,record,laboratory.rows])
  const sequenceId=patientMode?patientId:caseId
  const recordNavigation=useRecordSequenceNavigation({registry:patientMode?'patients':(typeof location.state?.limoxisFrom?.registry==='string'?location.state.limoxisFrom.registry:'surveillance-patients'),currentId:sequenceId,pathForId:id=>patientMode?`/patients/${id}`:`/surveillance/${id}`})

  async function load(preferred=''){
    setLoading(true);setError('')
    try{
      const roster=await loadPatients(tenant?.id,{isDemo})
      setPatients(roster)
      const selectedPatient=patientMode?roster.find(row=>String(row.id)===String(patientId)):null
      let rows=[]
      if(patientMode&&selectedPatient)rows=await repository.loadForPatient(selectedPatient)
      else if(caseId){const one=await repository.loadCase(caseId);rows=one?[one]:[]}
      setEpisodes(rows)
      const current=preferred||selectedEpisodeId||caseId||rows[0]?.id||''
      if(!patientMode)setSelectedEpisodeId(rows.some(row=>String(row.id)===String(current))?current:(rows[0]?.id||''))
      const patientForAdmissions=selectedPatient||roster.find(row=>rows.some(ep=>episodeBelongsToPatient(ep,row)))
      if(isDemo)setAdmissions(patientForAdmissions?await loadAdmissions(patientForAdmissions,{isDemo:true}):[])
      else if(patientForAdmissions?.recordId)try{setAdmissions(await loadAdmissions(patientForAdmissions.recordId))}catch{setAdmissions([])}
      else setAdmissions([])
      if(!isDemo&&tenant?.id)try{setDepartments((await loadDepartments(tenant.id)).filter(row=>row.is_active!==false));setClinicalLibraries(await loadManagementLibraries(tenant.id))}catch{setDepartments([])} else {setClinicalLibraries(demoLibrarySeed);setDepartments(demoLibrarySeed.departments.map(([elName,enName])=>({id:elName,name:language==='el'?elName:(enName||elName),nameEn:enName})))}
    }catch(err){setError(err?.message||t('actionFailed'))}
    finally{setLoading(false)}
  }
  // `load` reads `selectedEpisodeId`/`repository` to decide what to reselect after fetching,
  // and calling it updates that same state — depending on `load` here would refire it on
  // every completed load, an infinite loop. Re-run only when the identity being viewed changes.
  // eslint-disable-next-line react-hooks/exhaustive-deps
  useEffect(()=>{void load()},[tenant?.id,isDemo,patientMode,patientId,caseId])

  // Clinical-scale risk flags in the header; reloaded on tab change so a new assessment appears at once.
  useEffect(()=>{let alive=true;if(!patient)return;loadLatestPatientRiskFlags(tenant?.id,{isDemo}).then(value=>{if(alive)setRiskFlagRows(value)}).catch(()=>{});return()=>{alive=false}},[tenant?.id,isDemo,patient,tab])
  if(loading)return <Page title={t('clinicalRecords.patientRecord')}><div className="surface clinical-surface"><p>{t('loading')}</p></div></Page>
  if(error)return <Page title={t('clinicalRecords.patientRecord')}><EmptyState title={t('actionFailed')} description={error}/></Page>
  if(!patient&&!record)return <Page title={t('clinicalRecords.patientRecord')}><EmptyState title={t('noData')} description={t('clinicalRecords.noClinicalData')}/></Page>
  const subject=record||patient
  if(subject&&!canAccessRecord(subject))return <Page title={t('clinicalRecords.patientRecord')}><EmptyState title={t('scopeAccessDeniedTitle')} description={t('scopeAccessDeniedDescription')}/></Page>

  const name=language==='el'?(patient?.name||record?.patient):(patient?.nameEn||record?.patientEn||patient?.name||record?.patient)
  const code=patient?.id||record?.patientId
  const department=selectedAdmission?.department||(language==='el'?(record?.department||patient?.department):(record?.departmentEn||patient?.departmentEn||record?.department||patient?.department))
  const fmtDate=value=>value?new Intl.DateTimeFormat(locale).format(new Date(`${String(value).slice(0,10)}T12:00:00`)):'—'
  const fmtDateTime=value=>value?new Intl.DateTimeFormat(locale,{dateStyle:'short',timeStyle:'short'}).format(new Date(value)):'—'
  const canSurveillance=has(CAPABILITIES.VIEW_SURVEILLANCE)
  const canLab=has(CAPABILITIES.VIEW_LAB)||canSurveillance
  const canCreateLabSample=has(CAPABILITIES.MANAGE_LAB_SAMPLES)
  const canTherapy=has(CAPABILITIES.MANAGE_ANTIMICROBIAL_THERAPY)
  const tabs=patientMode&&!selectedAdmission?[]:[
    {id:'summary',label:t('summary'),icon:UserRound},
    {id:'surveillanceJourney',label:translate('copy.clinicalRecordCopy.surveillanceSamples',language==='el'?'el':'en'),icon:ListTree},
    {id:'clinicalData',label:t('clinicalRecords.clinicalData'),icon:Activity},
    ...(patientMode&&selectedAdmission?[{id:'clinicalScales',label:t('clinicalRecords.clinicalAssessments'),icon:Stethoscope}]:[]),
    {id:'documents',label:t('documents'),icon:FolderOpen},
    {id:'history',label:t('history'),icon:FileClock},
  ]
  const activeTab=tabs.some(item=>item.id===tab)?tab:'summary'

  function openAdmission(row){
    const scoped=episodes.filter(ep=>String(ep.admissionId||'')===String(row.id))
    setSelectedAdmissionId(row.id);setSelectedEpisodeId(scoped[0]?.id||'');setTab('summary')
  }
  function closeAdmission(){setSelectedAdmissionId('');setSelectedEpisodeId('');setTab('summary')}

  async function createEpisode(draft,targetPatient){
    const scopedDraft=selectedAdmission?{...draft,admissionId:selectedAdmission.id,admissionDate:selectedAdmission.admissionDate,departmentId:selectedAdmission.departmentId||draft.departmentId,department:selectedAdmission.department||draft.department,departmentEn:selectedAdmission.department||draft.departmentEn}:draft
    const created=await repository.createCase(targetPatient||patient,scopedDraft)
    if(sampleToLink){
      try{
        if(isDemo)await laboratory.repository.update(sampleToLink.id,{surveillanceCase:created.id})
        else await linkLaboratorySampleToSurveillance(tenant?.id,sampleToLink.recordId,created.id)
        await laboratory.reload()
      }catch(linkError){notify(linkError?.message||(translate('copy.clinicalRecordCopy.surveillanceWasCreatedButTheSample',language==='el'?'el':'en')),'error')}
    }
    setEpisodes(current=>[...current.filter(row=>String(row.id)!==String(created.id)),created]);setSelectedEpisodeId(created.id);notify(t('surveillanceCreated'),'success');return created
  }

  async function clearOwnerClinicalTestData(){
  if(role!=='platform_owner'||!patient||!selectedAdmission)return
  try{
    for(const sample of admissionSamples)await laboratory.repository.remove?.(sample.id||sample.recordId)
    for(const ep of admissionEpisodes)await repository.voidCase(ep,'Platform Owner test data reset')
    setSelectedEpisodeId('');setSampleToLink(null);await laboratory.reload();await load()
    setClearTestOpen(false);notify(translate('copy.clinicalRecordCopy.clinicalTestSurveillanceAndSamplesCleared',language==='el'?'el':'en'),'success')
  }catch(err){notify(err?.message||t('actionFailed'),'error')}
}

  async function createAdmissionSample(draft){
    if(!patient||creatingAdmissionSampleRef.current)return null
    // Outside the patient route (/surveillance/:id) there is no selected admission:
    // the episode's own department is used instead, so follow-up samples still save.
    const admission=selectedAdmission||{departmentId:record?.departmentId||null,department:record?.department||''}
    creatingAdmissionSampleRef.current=true
    try{
      const created=await laboratory.createSample({patientRecordId:patient.recordId||null,draft:{...draft,patient:patient.name,patientEn:patient.nameEn||patient.name,patientId:patient.id,departmentId:admission.departmentId||null,department:admission.department||patient.department||'',departmentEn:admission.department||patient.departmentEn||patient.department||'',subjectType:'patient',subjectName:patient.name,subjectNameEn:patient.nameEn||patient.name,subjectCode:patient.id}})
      notify(translate('copy.clinicalRecordCopy.sampleRecorded',language==='el'?'el':'en'),'success')
      if(!patientMode)await load()
      return created
    }finally{creatingAdmissionSampleRef.current=false}
  }

  const shellSubtitle=selectedAdmission?`${selectedAdmission.department||'—'} · ${t('clinicalRecords.admission')}: ${fmtDate(selectedAdmission.admissionDate)}`:(patientMode?(patient?.hospitalRecordNumber||t('clinicalRecords.patientRecord')):`${department||'—'} · ${t('clinicalRecords.admission')}: ${fmtDate(record?.admissionDate||patient?.admissionDate)}`)
  const shellStatus=selectedAdmission?.status||record?.status||patient?.status||'active'
  return <Page fill title={name} subtitle={code}><EntityRecordShell className={`patient-record-shell workspace-fill${activeTab==='clinicalScales'?' record-secondary-tab-active':''}`} avatar={name?.split(' ').map(x=>x?.[0]).slice(0,2).join('')} eyebrow={code} title={name} subtitle={shellSubtitle} status={<><span className={`status-badge ${shellStatus==='active'?'active':''}`}>{t(shellStatus)}</span>{record?.resistance&&<span className="status-badge danger">{record.resistance}</span>}{patient&&<ClinicalRiskFlags rows={riskFlagRows[patient.recordId]||riskFlagRows[patient.id]||[]} language={language} compact/>}</>} recordNavigation={!patientMode||!selectedAdmission?recordNavigation:null} headerActions={selectedAdmission||!patientMode?<PrintExportActions onExport={()=>downloadRecordJson({patient,admission:selectedAdmission,record,episodes:admissionEpisodes,admissions},{filename:record?.id||code})}/>:null} tabs={tabs} activeTab={activeTab} onTabChange={setTab} onBack={patientMode&&selectedAdmission?closeAdmission:goBack} backLabel={patientMode&&selectedAdmission?(translate('copy.clinicalRecordCopy.backToAdmissions',language==='el'?'el':'en')):(patientMode?t('clinicalRecords.backToPatients'):t('clinicalRecords.backToSurveillance'))}>
    {patientMode&&!selectedAdmission&&<PatientAdmissionsHome patient={patient} rows={admissions} episodes={episodes} tenantId={tenant?.id} isDemo={isDemo} departments={departments} canEdit={has(CAPABILITIES.EDIT_PATIENT)} t={t} language={language} fmtDate={fmtDate} onAdded={row=>setAdmissions(current=>[row,...current])} onChanged={()=>load()} onSelect={openAdmission} actions={<PatientSummaryActions patient={patient} departments={departments} onReload={()=>load()} onDeleted={goBack}/>}/>}
    {(!patientMode||selectedAdmission)&&activeTab==='summary'&&<CanonicalSummary patient={patient} admission={selectedAdmission} record={record} tenantId={tenant?.id} isDemo={isDemo} departments={departments} canEdit={patientMode&&has(CAPABILITIES.EDIT_PATIENT)} showPatientActions={patientMode} onDeleted={goBack} onChanged={()=>load()} t={t} language={language} fmtDate={fmtDate}/>}
    {(!patientMode||selectedAdmission)&&activeTab==='surveillanceJourney'&&<SurveillanceWorkspace samples={patientMode?admissionSamples:recordSamples} episodes={admissionEpisodes} selectedId={record?.id} onSelect={setSelectedEpisodeId} onCreate={()=>{setSampleToLink(null);setCreateOpen(true)}} onCreateFromSample={sample=>{setSampleToLink(sample);setCreateOpen(true)}} onCreateSample={patient?createAdmissionSample:null} onClearTestData={patientMode&&role==='platform_owner'?()=>setClearTestOpen(true):null} canCreate={has(CAPABILITIES.CREATE_SURVEILLANCE)} canCreateSample={canCreateLabSample} repository={repository} onReload={preferred=>load(preferred||record?.id)} t={t} language={language} fmtDate={fmtDate} fmtDateTime={fmtDateTime} libraries={clinicalLibraries} organizationId={tenant?.id} isDemo={isDemo} onLibraryAdded={async(key,item)=>{if(isDemo){setClinicalLibraries(current=>({...current,[key]:[...(current[key]||[]),item]}));return item}const created=await createManagementLibraryItem(tenant.id,key,{nameEl:item[0],nameEn:item[1]||item[0]});setClinicalLibraries(current=>({...current,[key]:[...(current[key]||[]),created]}));return created}} permissions={{canAssess:has(CAPABILITIES.RECORD_CLINICAL_ASSESSMENT),canLab,canClassifyResistance:has(CAPABILITIES.CLASSIFY_RESISTANCE),canIsolation:has(CAPABILITIES.MANAGE_ISOLATION),canTherapy,canReassess:has(CAPABILITIES.REASSESS_SURVEILLANCE),canOutcome:has(CAPABILITIES.RECORD_SURVEILLANCE_OUTCOME)||has(CAPABILITIES.CLOSE_SURVEILLANCE),canEdit:has(CAPABILITIES.EDIT_SURVEILLANCE),canDelete:has(CAPABILITIES.DELETE_SURVEILLANCE),canReopen:has(CAPABILITIES.REOPEN_SURVEILLANCE)}}/>}
    {activeTab==='clinicalData'&&record&&<ClinicalSnapshot record={record} t={t} language={language} fmtDate={fmtDate}/>}
    {activeTab==='clinicalScales'&&patient&&selectedAdmission&&<PatientClinicalScalesPanel organizationId={tenant?.id} patient={patient} admission={selectedAdmission} isDemo={isDemo} language={language} canRecord={has(CAPABILITIES.RECORD_CLINICAL_ASSESSMENT)}/>}
    {activeTab==='clinicalData'&&!record&&<EmptyState title={translate('copy.clinicalRecordCopy.noClinicalRecordYet',language==='el'?'el':'en')} description={translate('copy.clinicalRecordCopy.thisAdmissionHasNoActiveSurveillance',language==='el'?'el':'en')}/>}
    {activeTab==='documents'&&record&&(!isDemo&&record.recordId?<DocumentsWorkspace title={translate('copy.clinicalRecordCopy.documents',language==='en'?'en':'el')} disabled={!has(CAPABILITIES.RECORD_CLINICAL_ASSESSMENT)} organizationId={tenant?.id} entityType="clinical_case" entityId={record.recordId}/>:isDemo?<DocumentsWorkspace title={translate('copy.clinicalRecordCopy.documents',language==='en'?'en':'el')} disabled={!has(CAPABILITIES.RECORD_CLINICAL_ASSESSMENT)} value={demoDocuments[record.id]||[]} onChange={files=>setDemoDocuments(current=>({...current,[record.id]:files}))}/>:<div className="inline-empty">{t('clinicalRecords.noAttachments')}</div>)}
    {activeTab==='documents'&&!record&&<EmptyState title={translate('copy.clinicalRecordCopy.noDocumentsYet',language==='el'?'el':'en')} description={translate('copy.clinicalRecordCopy.surveillanceDocumentsWillAppearHereAfter',language==='el'?'el':'en')}/>}
    {activeTab==='history'&&record&&<Timeline record={record} t={t} language={language} fmtDateTime={fmtDateTime}/>}
    {activeTab==='history'&&!record&&<EmptyState title={translate('copy.clinicalRecordCopy.noSurveillanceHistoryYet',language==='el'?'el':'en')} description={translate('copy.clinicalRecordCopy.theActivityHistoryWillAppearHere',language==='el'?'el':'en')}/>}
    {clearTestOpen&&<ObserverDialog title={translate('copy.clinicalRecordCopy.clearClinicalTestData',language==='el'?'el':'en')} width="medium" onClose={()=>setClearTestOpen(false)}><p>{translate('copy.clinicalRecordCopy.surveillanceEpisodesAndSamplesShownFor',language==='el'?'el':'en')}</p><div className="dialog-actions"><Button variant="secondary" onClick={()=>setClearTestOpen(false)}>{t('cancel')}</Button><Button onClick={clearOwnerClinicalTestData}>{translate('copy.clinicalRecordCopy.confirmClear',language==='el'?'el':'en')}</Button></div></ObserverDialog>}
    {createOpen&&<NewSurveillanceFlow patient={patient} patients={patients} departments={departments} initialSample={sampleToLink} onPatientsChange={setPatients} onClose={()=>{setCreateOpen(false);setSampleToLink(null);void load(selectedEpisodeId)}} onCreate={createEpisode} onCancelCreated={async(caseRecord,reason)=>{await repository.voidCase(caseRecord,reason);setSelectedEpisodeId(null);await load()}} onSaveAssessment={(caseRecord,draft)=>repository.saveAssessment(caseRecord,draft)} onRequestSample={(caseRecord,draft)=>repository.requestSample(caseRecord,draft)} onSaveIsolation={(caseRecord,draft)=>draft.required===false?repository.setIsolationNotRequired(caseRecord):repository.beginIsolation(caseRecord,draft)} onRecordChange={updated=>{setEpisodes(current=>current.map(row=>row.id===updated.id?updated:row));setSelectedEpisodeId(updated.id)}}/>}
  </EntityRecordShell></Page>
}

function PatientAdmissionsHome({patient,rows,episodes,tenantId,isDemo,departments,canEdit,t,language,fmtDate,onAdded,onChanged,onSelect,actions}){
  // Ages under a year read as "N days" (matching NHSN's ≤1-year pediatric
  // population) rather than the years figure that would round every
  // neonate down to "0" and hide clinically relevant age.
  const ageInDays=patient?.dateOfBirth?Math.max(0,Math.floor((Date.now()-new Date(`${patient.dateOfBirth}T12:00:00`).getTime())/86400000)):null
  const ageLabel=ageInDays==null?'—':ageInDays<366?`${ageInDays} ${translate('copy.clinicalRecordCopy.days',language==='el'?'el':'en')}`:`${Math.floor(ageInDays/365.25)} ${translate('copy.clinicalRecordCopy.years',language==='el'?'el':'en')}`
  const profile=[
    [translate('copy.clinicalRecordCopy.patientCode',language==='el'?'el':'en'),patient?.id],
    [translate('copy.clinicalRecordCopy.hospitalRecordNumber',language==='el'?'el':'en'),patient?.hospitalRecordNumber],
    // Separate surname / first name (as in the patient form) instead of one
    // "full name" field whose order differed from the header.
    [translate('copy.clinicalRecordCopy.lastName',language==='el'?'el':'en'),(language==='en'&&patient?.lastNameEn)||patient?.lastName||(!patient?.firstName&&patient?.name)||'—'],
    [translate('copy.clinicalRecordCopy.firstName',language==='el'?'el':'en'),(language==='en'&&patient?.firstNameEn)||patient?.firstName||'—'],
    [translate('copy.clinicalRecordCopy.fatherName',language==='el'?'el':'en'),(language==='en'&&patient?.patronymicEn)||patient?.fatherName||patient?.patronymic],
    [translate('copy.clinicalRecordCopy.dateOfBirthAge',language==='el'?'el':'en'),patient?.dateOfBirth?`${fmtDate(patient.dateOfBirth)} · ${ageLabel}`:'—'],
    patient?.birthWeightGrams?[translate('copy.clinicalRecordCopy.birthWeight',language==='el'?'el':'en'),`${patient.birthWeightGrams} g`]:null,
    patient?.gestationalAgeWeeks?[translate('copy.clinicalRecordCopy.gestationalAge',language==='el'?'el':'en'),`${patient.gestationalAgeWeeks} ${translate('copy.clinicalRecordCopy.wk',language==='el'?'el':'en')}`]:null,
    [translate('copy.clinicalRecordCopy.sex',language==='el'?'el':'en'),patient?.sex?t(patient.sex):'—'],
    [translate('copy.clinicalRecordCopy.currentDepartment',language==='el'?'el':'en'),patient?.department||'—'],
  ].filter(Boolean)
  return <div className="patient-home-layout"><section className="patient-home-details patient-profile-card"><div className="record-section-header"><div><h3>{translate('copy.clinicalRecordCopy.patientDetails',language==='el'?'el':'en')}</h3><p>{translate('copy.clinicalRecordCopy.coreIdentityAndCurrentAdmissionInformation',language==='el'?'el':'en')}</p></div>{actions}</div><div className="patient-profile-grid">{profile.map(([label,value])=><div key={label} className="patient-profile-item"><span>{label}</span><strong>{value||'—'}</strong></div>)}</div>{patient?.notes&&<div className="patient-profile-note"><span>{translate('copy.clinicalRecordCopy.notes',language==='el'?'el':'en')}</span><p>{patient.notes}</p></div>}</section><AdmissionsPanel rows={rows} episodes={episodes} patient={patient} tenantId={tenantId} isDemo={isDemo} departments={departments} canEdit={canEdit} t={t} language={language} fmtDate={fmtDate} onAdded={onAdded} onChanged={onChanged} onSelect={onSelect}/></div>
}
// Admission summary: one info sheet for the stay (no duplicate status — the
// header already shows it) and one for the current surveillance episode,
// in the same info-sheet style as the rest of the record instead of six
// differently tinted tiles. Emphasis uses status badges only.
// Both ids must be present to match: two missing record ids (every demo
// patient) used to compare equal, so the first patient in the roster was shown
// on every surveillance record.
