function IsolationDialog({t,onClose,onSave}){const {language}=useLanguage();const [d,setD]=useState({precautions:['contact'],room:'',reason:'',startedAt:new Date().toISOString().slice(0,10),reviewDue:''});return <SimpleDialog title={translate('copy.clinicalRecordCopy.isolationTransmissionBasedPrecautions',language==='el'?'el':'en')} t={t} onClose={onClose} onSave={()=>onSave(d)} disabled={!d.reason}><label><span>{translate('copy.clinicalRecordCopy.precautions',language==='el'?'el':'en')}</span><select value={d.precautions[0]} onChange={e=>setD(x=>({...x,precautions:[e.target.value]}))}><option value="contact">{translate('copy.clinicalRecordCopy.contactPrecautions',language==='el'?'el':'en')}</option><option value="droplet">{translate('copy.clinicalRecordCopy.dropletPrecautions',language==='el'?'el':'en')}</option><option value="airborne">{translate('copy.clinicalRecordCopy.airbornePrecautions',language==='el'?'el':'en')}</option><option value="protective">{translate('copy.clinicalRecordCopy.protectiveIsolation',language==='el'?'el':'en')}</option></select></label><label><span>{translate('copy.clinicalRecordCopy.roomBed',language==='el'?'el':'en')}</span><input value={d.room} onChange={e=>setD(x=>({...x,room:e.target.value}))}/></label><ManualDateField label={translate('copy.clinicalRecordCopy.startDate',language==='el'?'el':'en')} value={d.startedAt} onChange={v=>setD(x=>({...x,startedAt:v}))}/><ManualDateField label={translate('copy.clinicalRecordCopy.nextReview',language==='el'?'el':'en')} optional value={d.reviewDue} onChange={v=>setD(x=>({...x,reviewDue:v}))}/><label className="entry-span-2"><span>{translate('copy.clinicalRecordCopy.reason',language==='el'?'el':'en')}</span><textarea value={d.reason} onChange={e=>setD(x=>({...x,reason:e.target.value}))}/></label></SimpleDialog>}
function EndDialog({title,t,onClose,onSave}){const [d,setD]=useState({endedAt:new Date().toISOString().slice(0,10),reason:''});return <SimpleDialog title={title} t={t} onClose={onClose} onSave={()=>onSave(d)}><ManualDateField label={t('endDate')} value={d.endedAt} onChange={v=>setD(x=>({...x,endedAt:v}))}/><label className="entry-span-2"><span>{t('reason')}</span><textarea value={d.reason} onChange={e=>setD(x=>({...x,reason:e.target.value}))}/></label></SimpleDialog>}
function ReassessmentDialog({t,onClose,onSave}){const {language}=useLanguage();const [d,setD]=useState({date:new Date().toISOString().slice(0,10),status:'stable',decision:'continueTreatment',notes:'',nextReviewDue:''});return <SimpleDialog title={translate('copy.clinicalRecordCopy.reassessment',language==='el'?'el':'en')} t={t} onClose={onClose} onSave={()=>onSave(d)}><ManualDateField label={translate('copy.clinicalRecordCopy.date',language==='el'?'el':'en')} value={d.date} onChange={v=>setD(x=>({...x,date:v}))}/><label><span>{translate('copy.clinicalRecordCopy.clinicalStatus',language==='el'?'el':'en')}</span><select value={d.status} onChange={e=>setD(x=>({...x,status:e.target.value}))}><option value="clinicalImprovement">{translate('copy.clinicalRecordCopy.clinicalImprovement',language==='el'?'el':'en')}</option><option value="stable">{translate('copy.clinicalRecordCopy.stable',language==='el'?'el':'en')}</option><option value="deterioration">{translate('copy.clinicalRecordCopy.deterioration',language==='el'?'el':'en')}</option></select></label><ManualDateField label={translate('copy.clinicalRecordCopy.nextReview',language==='el'?'el':'en')} optional value={d.nextReviewDue} onChange={v=>setD(x=>({...x,nextReviewDue:v}))}/><label className="entry-span-2"><span>{translate('copy.clinicalRecordCopy.notes',language==='el'?'el':'en')}</span><textarea value={d.notes} onChange={e=>setD(x=>({...x,notes:e.target.value}))}/></label></SimpleDialog>}
function OutcomeDialog({t,onClose,onSave}){const [d,setD]=useState({status:'resolved',date:new Date().toISOString().slice(0,10),notes:''});return <SimpleDialog title={t('outcome')} t={t} onClose={onClose} onSave={()=>onSave(d)}><label><span>{t('status')}</span><select value={d.status} onChange={e=>setD(x=>({...x,status:e.target.value}))}><option value="resolved">{t('resolved')}</option><option value="improved">{t('improved')}</option><option value="transferred">{t('transferred')}</option><option value="deceased">{t('deceased')}</option></select></label><ManualDateField label={t('date')} value={d.date} onChange={v=>setD(x=>({...x,date:v}))}/><label className="entry-span-2"><span>{t('notes')}</span><textarea value={d.notes} onChange={e=>setD(x=>({...x,notes:e.target.value}))}/></label></SimpleDialog>}
function ReasonDialog({title,t,reason,setReason,onClose,onSave}){return <SimpleDialog title={title} t={t} onClose={onClose} onSave={onSave} disabled={!reason.trim()}><label className="entry-span-2"><span>{t('reasonRequired')}</span><textarea rows={4} value={reason} onChange={e=>setReason(e.target.value)} autoFocus/></label></SimpleDialog>}
